BEGIN TRANSACTION;
CREATE TABLE "akg" (
"Parameter" TEXT,
  "AKG Harian" INTEGER,
  "Target PMT (25%)" REAL
);
CREATE TABLE "evaluasi_forecast" (
"Komoditas" TEXT,
  "Harga_Aktual_Rata2" REAL,
  "Harga_Prediksi_Rata2" REAL,
  "MAE" INTEGER,
  "RMSE" INTEGER,
  "MAPE (%)" REAL
);
CREATE TABLE "gwo_params" (
"No" INTEGER,
  "Komoditas" TEXT,
  "Harga Forecast (Rp/kg)" REAL,
  "Energi (kkal/100 g)" REAL,
  "Protein (g/100 g)" REAL,
  "Lemak (g/100 g)" REAL,
  "Karbohidrat (g/100 g)" REAL
);
CREATE TABLE "harga_pangan" (
"Tanggal" TEXT,
  "Beras Premium" INTEGER,
  "Daging Ayam Ras" REAL,
  "Telur Ayam Ras" INTEGER,
  "Ikan Kembung" INTEGER,
  "Wortel" INTEGER,
  "Kentang" INTEGER,
  "Buncis" INTEGER,
  "Daging Sapi" INTEGER
);
CREATE TABLE "hasil_forecast" (
"Tanggal" TEXT,
  "Beras Premium" REAL,
  "Daging Ayam Ras" REAL,
  "Telur Ayam Ras" REAL,
  "Ikan Kembung" TEXT,
  "Wortel" REAL,
  "Kentang" REAL,
  "Buncis" REAL,
  "Daging Sapi" REAL
);
CREATE TABLE "menu_pmt" (
"Menu" TEXT,
  "Beras Premium" INTEGER,
  "Daging Ayam Ras" INTEGER,
  "Telur Ayam Ras" INTEGER,
  "Ikan Kembung" INTEGER,
  "Wortel" INTEGER,
  "Kentang" INTEGER,
  "Daging Sapi" INTEGER,
  "Buncis" INTEGER
);
CREATE TABLE "tkpi" (
"Komoditas" TEXT,
  "Energi (kkal)" INTEGER,
  "Protein (g)" REAL,
  "Lemak (g)" REAL,
  "Karbohidrat (g)" REAL,
  "Fe (mg)" REAL,
  "Zn (mg)" REAL
);
COMMIT;
